const cfg=$('Configuração Bootstrap').first().json;
  if(cfg.documentationLayout!=='separated'){
    throw new Error('documentationLayout inválido: '+cfg.documentationLayout+'. Use separated.');
  }
  const exists=typeof $json.sha==='string';
  if(exists&&!cfg.forceBootstrap){
    throw new Error('Bootstrap já concluído para '+cfg.projectSlug+'. Use forceBootstrap somente com revisão explícita.');
  }
  return [{json:cfg}];

const cfg=$('Configuração Bootstrap').first().json;
  const projects=$input.first().json.payloads??[];
  const project=projects.find(item=>item.projectSlug===cfg.projectSlug);
  if(!project) throw new Error('Core não retornou o projeto '+cfg.projectSlug);
  const encodePath=value=>String(value).split('/').map(encodeURIComponent).join('/');
  const repositoryUrl='https://github.com/'+encodeURIComponent(cfg.owner)+'/'+encodeURIComponent(cfg.repository);
  const documentationPath='projects/'+project.projectSlug;
  const readmeUrl=repositoryUrl+'/blob/'+encodePath(cfg.branch)+'/'+encodePath(documentationPath)+'/README.md';
  const repositoryContext={
    owner:cfg.owner,
    repository:cfg.repository,
    branch:cfg.branch,
    repositoryUrl,
    readmeUrl,
    url:readmeUrl,
    documentationPath
  };
  return [{json:{...project,aiMode:cfg.aiMode,documentationLayout:cfg.documentationLayout,documentationMode:'bootstrap',repositoryContext}}];

const project=$('Selecionar projeto').first().json;
const maximumBytes=120000;
const decodeFile=nodeName=>{
  let data={};
  try{data=$(nodeName).first().json??{};}catch{return {markdown:'',sha:null};}
  if(typeof data.content!=='string') return {markdown:'',sha:null};
  let markdown='';
  try{markdown=Buffer.from(data.content.replace(/\s/g,''),'base64').toString('utf8').trim();}
  catch{throw new Error(nodeName+' não pôde ser decodificado.');}
  if(Buffer.byteLength(markdown,'utf8')>maximumBytes){
    throw new Error(nodeName+' excede 120000 bytes. Reduza o arquivo antes do Bootstrap.');
  }
  return {markdown,sha:typeof data.sha==='string'?data.sha:null};
};
const sanitize=value=>String(value??'')
  .replace(/Bearer\s+[A-Za-z0-9._~+\/=\-]+/gi,'Bearer {{REDACTED_TOKEN}}')
  .replace(/\b(?:gh[pousr]_[A-Za-z0-9_]{20,}|github_pat_[A-Za-z0-9_]{20,}|sk-[A-Za-z0-9_-]{16,})\b/g,'{{REDACTED_TOKEN}}')
  .replace(/((?:api[_ -]?key|access[_ -]?token|token|secret|password)\s*[:=]\s*)[^\s\x60\"'<>]+/gi,'$1{{REDACTED_VALUE}}')
  .replace(/https?:\/\/(?:localhost|127\.0\.0\.1|10\.\d+\.\d+\.\d+|192\.168\.\d+\.\d+)(?::\d+)?/gi,'https://internal.example');
const readme=decodeFile('Consultar README anterior');
const technical=decodeFile('Consultar documento técnico anterior');
const internal=decodeFile('Consultar documento interno anterior');
const decisionsAndLearnings=decodeFile('Consultar decisões e aprendizados anteriores');
const projectsIndexReadme=decodeFile('Consultar README da pasta projects');
const legacyReview=decodeFile('Consultar PR_REVIEW legado');
const previousDocumentation=(readme.markdown||technical.markdown||internal.markdown)
  ? {
      readmeMarkdown:sanitize(readme.markdown),
      technicalMarkdown:sanitize(technical.markdown),
      internalMarkdown:sanitize(internal.markdown),
      sourceShas:{readme:readme.sha,technical:technical.sha,internal:internal.sha},
      sanitized:true
    }
  : null;
return [{json:{
  ...project,
  documentationLayout:'separated',
  previousDocumentation,
  decisionsAndLearnings:{markdown:decisionsAndLearnings.markdown,sha:decisionsAndLearnings.sha},
  projectsIndexReadme:{markdown:projectsIndexReadme.markdown,sha:projectsIndexReadme.sha},
  legacyReviewFileExists:Boolean(legacyReview.sha)
}}];

const cfg=$('Configuração Bootstrap').first().json;
  const input=$input.first().json;
  const project=Array.isArray(input.payloads)?input.payloads[0]:input;
  if(!project?.projectSlug) throw new Error('Projeto ausente na preparação do Bootstrap.');
  const manifest=JSON.parse(project.technicalFiles?.['project.json']??'{}');
  const today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit',day:'2-digit'})
    .format(new Date()).replace(/-/g,'.');
  const updatedManifest={
    ...manifest,
    bootstrapCompleted:true,
    sourceOfTruth:'github',
    aiMode:cfg.aiMode,
    documentationLayout:'separated',
    documentationSchemaVersion:2,
    currentVersion:today+'.1',
    bootstrapAt:new Date().toISOString(),
    reviewRequired:true
  };
  const technicalFiles={...(project.technicalFiles??{})};
  delete technicalFiles['project.json'];
  const relativeFiles={
    ...technicalFiles,
    ...(project.humanFiles??{}),
    'project.json':JSON.stringify(updatedManifest,null,2)
  };
  const projectFiles=Object.fromEntries(Object.entries(relativeFiles).map(([file,content])=>[
    'projects/'+project.projectSlug+'/'+file,content
  ]));
  const repositoryFiles=Object.fromEntries(Object.entries(project.repositoryFiles??{})
    .filter(([file,content])=>file==='projects/README.md'&&typeof content==='string'));
  const files={...projectFiles,...repositoryFiles};
  const deletePaths=(project.repositoryDeletePaths??[])
    .map(String).filter(file=>file==='PR_REVIEW.md');
  return [{json:{
    owner:cfg.owner,
    repository:cfg.repository,
    branch:cfg.branch,
    projectSlug:project.projectSlug,
    files,
    deletePaths,
    commitMessage:'docs('+project.projectSlug+'): bootstrap separated documentation'
  }}];

const publication=$input.first().json;
  const cfg=$('Configuração Bootstrap').first().json;
  return [{json:{
    status:'bootstrap-complete',
    projectSlug:cfg.projectSlug,
    aiMode:cfg.aiMode,
    documentationLayout:cfg.documentationLayout,
    repository:cfg.owner+'/'+cfg.repository,
    branch:cfg.branch,
    publication,
    reviewRequired:true
  }}];
